/* ---- Hermanos de Liliana: por testimonio familiar, sin documento todavía ---- */
ivonne:{t:1,n:"Ivonne De Faccio",d:"~1925-45",b:"friuli",pa:["gbD","santaC"],
  note:"Hermana de Liliana. Sólo por testimonio familiar: no hay documento. «Ivonne» es la forma francesa de Yvonne — llamativa en el Friuli de entreguerras, porque el fascismo desalentaba los nombres extranjeros. Puede indicar un nacimiento posterior a 1945.",
  c:[["Testimonio familiar de Federico Carlini, 23-ago-2026"]]},
vilma:{t:1,n:"Vilma De Faccio",d:"~1925-45",b:"friuli",pa:["gbD","santaC"],
  note:"Hermana de Liliana. Sólo por testimonio familiar. «Vilma» se populariza en Italia en los años 30 y 40.",
  c:[["Testimonio familiar de Federico Carlini, 23-ago-2026"]]},
franca:{t:1,n:"Franca De Faccio",d:"~1925-45",b:"friuli",pa:["gbD","santaC"],
  note:"Hermana de Liliana. Sólo por testimonio familiar. «Franca» es de los nombres más frecuentes en la Italia de los años 30 y 40.\n\nTuvo una hija, ANNA, y por ella la rama sigue dos generaciones más: las nietas de Franca son Chiara y Giulia Polidori.",
  f:[["Hija","Anna","Testimonio de Federico Carlini, 27 de agosto de 2026."]],
  c:[["Testimonio familiar de Federico Carlini, 23-ago-2026"],
     ["Testimonio de Federico Carlini, 27-ago-2026","La hija y las dos nietas."]]},
annaDF:{t:1,hyp:1,n:"Anna Gatti",d:"?",b:"friuli",pa:["franca"],
  note:"Hija de Franca De Faccio. El apellido no lo aportó el testimonio: se dedujo, y por eso entra como hipótesis.\n\nEl razonamiento: sus hijas se apellidan POLIDORI, o sea que Anna se casó con un Polidori y Polidori no es su apellido de soltera. Pero el testimonio dice que el tío de las chicas es STEFANO GATTI. Un tío puede serlo por dos caminos, y el más simple es que sea hermano de la madre — lo que haría a Anna una GATTI de soltera, hija de Franca De Faccio y de un señor Gatti.\n\nEs una deducción de una sola pieza y puede caerse: Stefano podría ser tío por el lado Polidori, o marido de una hermana. Alcanza con preguntar de quién es hermano Stefano para confirmarlo o tirarlo abajo.",
  f:[["Apellido","Gatti — deducido, no aportado","Si Stefano Gatti es hermano de Anna, Anna es Gatti de soltera y Franca se casó con un Gatti. Hay que confirmarlo preguntando de quién es hermano Stefano."],
     ["Hijas","Chiara y Giulia Polidori"]],
  c:[["Testimonio de Federico Carlini, 27-ago-2026"]]},
stefanoGatti:{t:1,hyp:1,n:"Stefano Gatti",d:"?",b:"friuli",pa:["franca"],
  note:"El testimonio lo da como TÍO de Chiara y Giulia Polidori. Dónde colgarlo del árbol es, por ahora, una deducción.\n\nEstá puesto como hermano de Anna —o sea, otro hijo de Franca— porque es la lectura que explica el apellido de las dos: si Anna era Gatti de soltera, Stefano es su hermano y todo cierra con una sola suposición.\n\nPero puede estar mal. Podría ser tío por el lado del padre de las chicas, o estar casado con una hermana del padre. Es una de las preguntas más baratas de resolver que quedan en el árbol.",
  f:[["Vínculo","Tío de Chiara y Giulia Polidori","Es lo único que dice el testimonio. Que sea hermano de Anna es deducción."]],
  c:[["Testimonio de Federico Carlini, 27-ago-2026"]]},
chiaraPol:{t:1,n:"Chiara Polidori",d:"?",b:"friuli",pa:["annaDF"],
  note:"Hija de Anna, nieta de Franca De Faccio. Sólo por testimonio familiar.",
  c:[["Testimonio de Federico Carlini, 27-ago-2026"]]},
giuliaPol:{t:1,n:"Giulia Polidori",d:"?",b:"friuli",pa:["annaDF"],
  note:"Hija de Anna, nieta de Franca De Faccio. Sólo por testimonio familiar.",
  c:[["Testimonio de Federico Carlini, 27-ago-2026"]]},
giorgio:{t:1,n:"Giorgio De Faccio",d:"~1925-45",b:"friuli",pa:["gbD","santaC"],
  note:"Hermano de Liliana, y el único del grupo con nombre tradicional friulano.\n\nTuvo al menos tres hijos: PIERGIORGIO, DANIELLA y GIOVANNI De Faccio. Son los primos hermanos de Patricia, y la rama viva más cercana por el lado friulano fuera de la línea directa. Si alguno conserva papeles de familia —o simplemente memoria— es de los contactos más valiosos que quedan por abrir.",
  f:[["Hijos","Piergiorgio · Daniella · Giovanni De Faccio","Testimonio de Federico Carlini, 26 de agosto de 2026."]],
  c:[["Testimonio familiar de Federico Carlini, 23-ago-2026"],
     ["Testimonio de Federico Carlini, 26-ago-2026","Los nombres de los tres hijos."]]},
piergiorgioDF:{t:1,n:"Piergiorgio De Faccio",d:"?",b:"friuli",pa:["giorgio"],
  note:"Hijo de Giorgio De Faccio, primo hermano de Patricia. Sólo por testimonio familiar: no hay acta todavía. Su nombre repite el del padre, que es costumbre corriente en el Friuli.",
  c:[["Testimonio de Federico Carlini, 26-ago-2026"]]},
daniellaDF:{t:1,n:"Daniella De Faccio",d:"?",b:"friuli",pa:["giorgio"],
  note:"Hija de Giorgio De Faccio, prima hermana de Patricia. Sólo por testimonio familiar.",
  c:[["Testimonio de Federico Carlini, 26-ago-2026"]]},
giovanniDF:{t:1,n:"Giovanni De Faccio",d:"?",b:"friuli",pa:["giorgio"],
  note:"Hijo de Giorgio De Faccio, primo hermano de Patricia. Sólo por testimonio familiar.\n\nLleva el nombre del abuelo, Giovanni Battista De Faccio — la regla onomástica friulana funcionando igual que la siciliana del otro lado del árbol.",
  c:[["Testimonio de Federico Carlini, 26-ago-2026"]]},

